def is_majority(arr, n, element):
    # Helper function to find the first occurrence of an element
    def first_occurrence(arr, low, high, element):
        while low <= high:
            mid = (low + high) // 2
            if (mid == 0 or arr[mid - 1] < element) and arr[mid] == element:
                return mid
            elif arr[mid] < element:
                low = mid + 1
            else:
                high = mid - 1
        return -1

    # Helper function to find the last occurrence of an element
    def last_occurrence(arr, low, high, element):
        while low <= high:
            mid = (low + high) // 2
            if (mid == n - 1 or arr[mid + 1] > element) and arr[mid] == element:
                return mid
            elif arr[mid] > element:
                high = mid - 1
            else:
                low = mid + 1
        return -1

    # Find the first and last occurrence of the element
    first = first_occurrence(arr, 0, n - 1, element)
    if first == -1:  # Element not found in the array
        return False
    last = last_occurrence(arr, 0, n - 1, element)

    # Check if the count of the element is greater than n/2
    count = last - first + 1
    return count > n // 2

# Example usage:
assert is_majority([1, 2, 3, 3, 3, 3, 10], 7, 3) == True
