def lps(s: str) -> int:
    def longest_palindromic_subsequence(s):
        n = len(s)
        dp = [[0] * n for _ in range(n)]

        # Subsequences of length 1 are palindromic
        for i in range(n):
            dp[i][i] = 1

        # Check all substrings of length 2 and more
        for cl in range(2, n + 1):
            for i in range(n - cl + 1):
                j = i + cl - 1
                if s[i] == s[j]:
                    dp[i][j] = dp[i + 1][j - 1] + 2
                else:
                    dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

        return dp[0][n - 1]

    # Remove spaces and make the string case-insensitive
    s = ''.join(filter(str.isalnum, s)).upper()
    return longest_palindromic_subsequence(s)
