def max_Product(nums):
    if len(nums) < 2:
        raise ValueError("Array must contain at least two integers")

    # Initialize variables to track the two largest and two smallest numbers
    max1 = max2 = float('-inf')  # Two largest numbers
    min1 = min2 = float('inf')   # Two smallest numbers

    for num in nums:
        # Update the two largest numbers
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        # Update the two smallest numbers
        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    # Compare the product of the two largest numbers and the product of the two smallest numbers
    if max1 * max2 > min1 * min2:
        return (max2, max1)
    else:
        return (min1, min2)

# Example usage and tests
assert max_Product([1, 2, 3, 4, 7, 0, 8, 4]) == (7, 8)
assert max_Product([0, -1, -2, -4, 5, 0, -6]) == (-4, -6)
assert max_Product([-10, -3, 5, 6, -2]) == (-10, -3)
assert max_Product([0, 2]) == (0, 2)
```

