def extract_even(data):
    def process_element(element):
        if isinstance(element, tuple):  # Check if element is a tuple
            # Recursively process each element of the tuple and filter out uneven numbers
            return tuple(process_element(e) for e in element if isinstance(e, tuple) or (isinstance(e, int) and e % 2 == 0))
        elif isinstance(element, int) and element % 2 == 0:  # Check if element is an even integer
            return element
        return None  # Filter out anything that isn't a tuple or even integer

    # Process the top-level tuple and filter out None values
    return tuple(filter(lambda x: x is not None, (process_element(e) for e in data)))
