def pair_xor_Sum(nums, n):
    def xor_sum(nums):
        xor_total = 0
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                xor_total += nums[i] ^ nums[j]
        return xor_total

    if len(nums) != n:
        raise ValueError("The length of the input list does not match the given n.")

    return xor_sum(nums)

# Example usage and test
assert pair_xor_Sum([5, 9, 7, 6], 4) == 47
